class Solution {
    private static final int[][] DIRS = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
    private int answer;

    public int uniquePathsIII(int[][] grid) {
        int m = grid.length;
        int n = grid[0].length;
        int startRow = 0;
        int startCol = 0;
        int walkable = 0;

        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] != -1) {
                    walkable++;
                }
                if (grid[r][c] == 1) {
                    startRow = r;
                    startCol = c;
                }
            }
        }

        answer = 0;
        dfs(grid, startRow, startCol, walkable);
        return answer;
    }

    private void dfs(int[][] grid, int row, int col, int remaining) {
        if (row < 0 || row >= grid.length || col < 0 || col >= grid[0].length || grid[row][col] == -1) {
            return;
        }
        if (grid[row][col] == 2) {
            if (remaining == 1) {
                answer++;
            }
            return;
        }

        int original = grid[row][col];
        grid[row][col] = -1;
        for (int[] dir : DIRS) {
            dfs(grid, row + dir[0], col + dir[1], remaining - 1);
        }
        grid[row][col] = original;
    }
}

