class Solution {
    private static final int[][] DIRS = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
    private int rows;
    private int cols;
    private int target;
    private int allMask;
    private int[][] grid;
    private Map<Long, Integer> memo;

    public int uniquePathsIII(int[][] grid) {
        this.grid = grid;
        rows = grid.length;
        cols = grid[0].length;
        int start = 0;
        allMask = 0;
        target = 0;

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                int bit = 1 << (r * cols + c);
                if (grid[r][c] != -1) {
                    allMask |= bit;
                }
                if (grid[r][c] == 1) {
                    start = r * cols + c;
                } else if (grid[r][c] == 2) {
                    target = r * cols + c;
                }
            }
        }

        memo = new HashMap<>();
        return count(start, 1 << start);
    }

    private int count(int position, int mask) {
        if (position == target) {
            return mask == allMask ? 1 : 0;
        }
        long key = (((long) mask) << 20) | position;
        Integer cached = memo.get(key);
        if (cached != null) {
            return cached;
        }

        int row = position / cols;
        int col = position % cols;
        int total = 0;
        for (int[] dir : DIRS) {
            int nr = row + dir[0];
            int nc = col + dir[1];
            if (nr < 0 || nr >= rows || nc < 0 || nc >= cols || grid[nr][nc] == -1) {
                continue;
            }
            int next = nr * cols + nc;
            int bit = 1 << next;
            if ((mask & bit) == 0) {
                total += count(next, mask | bit);
            }
        }
        memo.put(key, total);
        return total;
    }
}

