class Solution {
    public int uniquePathsIII(int[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;
        int[][] id = new int[rows][cols];
        for (int[] row : id) {
            Arrays.fill(row, -1);
        }

        int cells = 0;
        int start = -1;
        int end = -1;
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == -1) {
                    continue;
                }
                id[r][c] = cells;
                if (grid[r][c] == 1) {
                    start = cells;
                } else if (grid[r][c] == 2) {
                    end = cells;
                }
                cells++;
            }
        }

        int[] adjacency = new int[cells];
        int[][] dirs = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (id[r][c] < 0) {
                    continue;
                }
                int mask = 0;
                for (int[] dir : dirs) {
                    int nr = r + dir[0];
                    int nc = c + dir[1];
                    if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && id[nr][nc] >= 0) {
                        mask |= 1 << id[nr][nc];
                    }
                }
                adjacency[id[r][c]] = mask;
            }
        }

        int allMask = (1 << cells) - 1;
        int[][] dp = new int[1 << cells][cells];
        dp[1 << start][start] = 1;
        for (int mask = 0; mask <= allMask; mask++) {
            for (int node = 0; node < cells; node++) {
                int ways = dp[mask][node];
                if (ways == 0 || node == end) {
                    continue;
                }
                int choices = adjacency[node] & ~mask;
                while (choices != 0) {
                    int bit = choices & -choices;
                    int next = Integer.numberOfTrailingZeros(bit);
                    dp[mask | bit][next] += ways;
                    choices -= bit;
                }
            }
        }
        return dp[allMask][end];
    }
}

