class Solution {
    private static final int[][] DIRS = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

    public int uniquePathsIII(int[][] grid) {
        int startRow = 0;
        int startCol = 0;
        int walkable = 0;
        for (int r = 0; r < grid.length; r++) {
            for (int c = 0; c < grid[0].length; c++) {
                if (grid[r][c] != -1) {
                    walkable++;
                }
                if (grid[r][c] == 1) {
                    startRow = r;
                    startCol = c;
                }
            }
        }
        return dfs(grid, startRow, startCol, walkable);
    }

    private int dfs(int[][] grid, int row, int col, int remaining) {
        if (row < 0 || row >= grid.length || col < 0 || col >= grid[0].length || grid[row][col] == -1) {
            return 0;
        }
        if (grid[row][col] == 2) {
            return remaining == 1 ? 1 : 0;
        }

        int original = grid[row][col];
        grid[row][col] = -1;
        if (!canStillReachAllRemaining(grid, row, col, remaining - 1)) {
            grid[row][col] = original;
            return 0;
        }

        int total = 0;
        for (int[] dir : DIRS) {
            total += dfs(grid, row + dir[0], col + dir[1], remaining - 1);
        }
        grid[row][col] = original;
        return total;
    }

    private boolean canStillReachAllRemaining(int[][] grid, int row, int col, int expected) {
        if (expected == 0) {
            return true;
        }
        int rows = grid.length;
        int cols = grid[0].length;
        boolean[][] seen = new boolean[rows][cols];
        ArrayDeque<int[]> queue = new ArrayDeque<>();
        for (int[] dir : DIRS) {
            int nr = row + dir[0];
            int nc = col + dir[1];
            if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && grid[nr][nc] != -1) {
                seen[nr][nc] = true;
                queue.offer(new int[]{nr, nc});
                break;
            }
        }
        if (queue.isEmpty()) {
            return false;
        }

        int reached = 0;
        while (!queue.isEmpty()) {
            int[] cell = queue.poll();
            reached++;
            for (int[] dir : DIRS) {
                int nr = cell[0] + dir[0];
                int nc = cell[1] + dir[1];
                if (nr >= 0 && nr < rows && nc >= 0 && nc < cols
                        && !seen[nr][nc] && grid[nr][nc] != -1) {
                    seen[nr][nc] = true;
                    queue.offer(new int[]{nr, nc});
                }
            }
        }
        return reached == expected;
    }
}

